-- Minimal isolated schema for exercising the actual order functions. No production data.
create schema auth; create schema private;
create role anon; create role authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth to authenticated;grant execute on function auth.uid() to authenticated;
create type public.fulfilment_type as enum ('TAKEAWAY','EAT_HERE');
create type public.order_status as enum ('NEW','ACCEPTED','PREPARING','READY','COMPLETED','CANCELLED');
create table public.customer_profiles(customer_id uuid primary key,auth_user_id uuid,full_name text,mobile_number text,mobile_verified_at timestamptz);
create table public.user_roles(auth_user_id uuid,role text);
create table public.order_settings(id integer primary key,ordering_enabled boolean,opens_at time,closes_at time,shop_timezone text,shop_lat numeric,shop_lng numeric,updated_at timestamptz);
alter table public.order_settings enable row level security;
create policy "order settings read" on public.order_settings for select to authenticated using(true);
grant select on public.order_settings, public.user_roles to authenticated;
create table public.menu_items(id uuid primary key,name text,category text,price numeric,listed boolean,available boolean);
create table public.orders(order_id uuid primary key default gen_random_uuid(),order_number bigint generated by default as identity,customer_id uuid,status public.order_status default 'NEW',fulfilment public.fulfilment_type,subtotal numeric,total numeric,notes text,customer_lat numeric,customer_lng numeric,distance_m integer,last_updated_by uuid,customer_phone text,phone_reverified_at timestamptz,far_order boolean,customer_eta_minutes integer,customer_expected_at timestamptz,discount_amount numeric default 0,promo_code text,scheduled_collection_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.order_items(order_item_id uuid primary key default gen_random_uuid(),order_id uuid,menu_item_id uuid,item_name text,unit_price numeric,quantity integer,line_total numeric,item_notes text);
create table public.order_status_history(order_id uuid,from_status public.order_status,to_status public.order_status,changed_by uuid);
create table private.order_collection_intents(intent_id uuid,auth_user_id uuid,consumed_at timestamptz,expires_at timestamptz,created_at timestamptz,customer_eta_minutes integer);
create table public.promotions(promotion_id uuid primary key,code text,active boolean,starts_at timestamptz,expires_at timestamptz,min_spend numeric,per_customer_limit integer,max_uses integer,discount_type text,discount_value numeric);
create table public.promotion_redemptions(promotion_id uuid,customer_id uuid,order_id uuid,discount_amount numeric);
create function public.distance_meters(numeric,numeric,numeric,numeric) returns integer language sql immutable as $$select 0$$;
